from __future__ import absolute_import
from taf.selenium.sbts.pages import v20b, v25r1


class Software(v25r1.Software):

    def __init__(self, driver, download_checker):
        super(Software, self).__init__(driver, download_checker)
        self._beam_set_realization_software = BeamSetRealizationSoftwarePage(driver, download_checker)


class BeamSetRealizationSoftwarePage(v20b.software.BeamSetRealizationSoftwarePage):

    def __init__(self, driver, download_checker):
        super(BeamSetRealizationSoftwarePage, self).__init__(driver, download_checker)
        self._view_panel = BeamSetRealizationSoftwarePageViewPanel(driver, download_checker)


class BeamSetRealizationSoftwarePageViewPanel(v20b.software.BeamSetRealizationSoftwarePageViewPanel):

    _CHECKBOX_XPATH = ("//*[contains(@class, 'bsr-table')]//tbody//tr"
                       "//div[contains(@class, 'checkbox') or contains(@role, 'checkbox')]")
    _DELETE_BUTTON_XPATH = "//*[@class='bsr-remove-button']//button[@ng-reflect-label='Delete']"
